struct command { void (*execute)(struct command *); void (*undo)(struct command *); void *payload; };
void *worker(void *unused) {
    for (;;) {
        pthread_mutex_lock(&q.lock);
        while (!q.head) pthread_cond_wait(&q.ready, &q.lock);   /* re-check in a loop */
        struct command *c = q_pop(&q);
        pthread_mutex_unlock(&q.lock);
        c->execute(c);        /* never run a command while holding the queue lock */
        history_push(c);      /* log / undo stack */
    }
}
